// ENTRADA (FASE 1): converte a mensagem do chat de teste do n8n para o FORMATO PADRÃO.
// Na Fase 2, um nó "Entrada WhatsApp → formato padrão" faz o mesmo e o resto do fluxo não muda.
//
// FORMATO PADRÃO:
//   canal, id_bruto (vira hash no banco), texto, imagem_base64, imagem_mime, imagem_bytes,
//   tem_audio, outro_arquivo
const item = $input.first();
const j = item.json || {};

let imagem_base64 = null, imagem_mime = null, imagem_bytes = 0;
let tem_audio = false, outro_arquivo = false;

for (const chave of Object.keys(item.binary || {})) {
  const mime = (item.binary[chave].mimeType || '').toLowerCase();
  if (mime.startsWith('image/') && !imagem_base64) {
    const buf = await this.helpers.getBinaryDataBuffer(0, chave);
    imagem_base64 = buf.toString('base64');
    imagem_mime = mime === 'image/jpg' ? 'image/jpeg' : mime;
    imagem_bytes = buf.length;
  } else if (mime.startsWith('audio/')) {
    tem_audio = true;
  } else if (!mime.startsWith('image/')) {
    outro_arquivo = true;
  }
}

return [{
  json: {
    canal: 'chat_n8n',
    id_bruto: 'chat:' + (j.sessionId || 'sem-sessao'),
    texto: (j.chatInput || '').toString().trim(),
    imagem_base64, imagem_mime, imagem_bytes, tem_audio, outro_arquivo,
  },
}];

// ===== Trechos comuns (vêm de n8n/codigo/_comum.js) =====
const MODELO_CLAUDE = 'claude-opus-5-5';
// Se a API do Claude reclamar do campo "fallbacks", troque para false.
const USAR_FALLBACK = true;

// Mensagens fixas do Zé (não passam pela IA)
const MSG = {
  CONSENTIMENTO:
    'Oi, eu sou o Zé da Farma! 👋 Eu vejo se o remédio da sua receita é de graça no Farmácia Popular e onde retirar.\n\n' +
    'Antes, um combinado rápido:\n' +
    '• Sou um projeto voluntário. NÃO sou canal oficial do governo.\n' +
    '• A foto da receita é lida por uma inteligência artificial (Claude, da Anthropic) só pra achar o nome do remédio. Eu não guardo a foto, nem nome, nem CPF.\n' +
    '• Guardo só um código no lugar do seu número e em que passo a conversa está, por até 24 horas.\n' +
    '• Nunca peço senha nem dados de banco.\n' +
    '• Escreva APAGAR a qualquer hora e eu apago seus dados.\n\n' +
    'Pode ser? Responda SIM pra continuar.',
  CONSENTIMENTO_NAO: 'Tudo bem! Não guardei nada. Se mudar de ideia, é só mandar um oi.',
  BOAS_VINDAS: 'Oba! Manda a foto da receita que eu vejo se tá na lista. Se preferir, escreve o nome do remédio.',
  PEDIR_RECEITA: 'Oi, eu sou o Zé! Manda a foto da receita que eu vejo se tá na lista. Também pode escrever o nome do remédio.',
  APAGADO: 'Pronto, apaguei seus dados. Se quiser usar de novo, é só mandar um oi.',
  RECOMECAR: 'Beleza, vamos começar de novo. Manda a foto da receita ou escreve o nome do remédio.',
  EXPIROU: 'Faz mais de um dia que a gente conversou, então comecei do zero.',
  FORA_CLINICO:
    'Essa eu não posso responder: dose, efeito, troca ou mistura de remédios é com o médico ou o farmacêutico. ' +
    'Eu só vejo se o remédio tá na lista do Farmácia Popular e onde retirar.',
  FORA_ESCOPO: 'Eu só sei falar do Farmácia Popular 🙂 Manda a foto da receita ou o nome do remédio que eu vejo se tá na lista.',
  NUNCA_PEDIMOS:
    'Atenção: eu nunca peço senha, cartão, Pix ou dados de banco. Não mande isso aqui. ' +
    'Se alguém pedir isso em nome do Farmácia Popular, é golpe.',
  NAO_PRECISA_CPF: 'Não precisa me mandar CPF nem documento, e eu não guardo esses dados. O CPF você mostra só lá na farmácia.',
  AUDIO: 'Ainda não consigo ouvir áudio. Manda a foto da receita ou escreve o nome do remédio, por favor.',
  IMAGEM_GRANDE: 'A foto ficou pesada demais pra mim. Tenta mandar de novo (pode ser um print), ou escreve o nome do remédio.',
  IMAGEM_TIPO: 'Não consegui abrir esse arquivo. Manda uma foto (JPG ou PNG) ou escreve o nome do remédio.',
  NAO_LEGIVEL: 'Não consegui ler a receita direitinho. Tenta outra foto, com boa luz e bem de pertinho, ou escreve o nome do remédio.',
  ERRO_TECNICO: 'Ops, tive um probleminha agora. Tenta de novo daqui a pouco, ou escreve o nome do remédio.',
  CONFIRMACAO_NAO: 'Sem problema! Manda a foto de novo, bem de pertinho e com luz, ou escreve o nome certo do remédio.',
  CONFIRMAR_DE_NOVO: 'Tá certo o que eu li? Responda SIM, ou escreva o nome certo do remédio.',
  PEDIR_CEP: 'Me manda seu CEP, só os números, que eu mostro as farmácias mais perto.',
  CEP_INVALIDO: 'Não entendi o CEP. Manda só os 8 números, assim: 01310100.',
  CEP_NAO_ACHADO: 'Não achei esse CEP. Confere e manda de novo, só os 8 números.',
  SEM_CEP: 'Tudo bem! Procure uma farmácia com a placa "Aqui tem Farmácia Popular". Se precisar, é só mandar outra receita.',
  O_QUE_LEVAR:
    'Pra retirar, leve: receita válida, documento com foto e CPF. ' +
    'Outra pessoa pode retirar por você, levando uma procuração.',
  INSUMO: 'Pra fralda geriátrica e absorvente, confirme na farmácia o que levar, porque as regras podem ser diferentes.',
  CONFIRA_ESTOQUE: 'Vale confirmar na farmácia se o remédio tá em estoque. Se precisar de outra receita, é só mandar a foto.',
  SEM_FARMACIA_PERTO:
    'Ainda não tenho farmácias cadastradas perto desse CEP. ' +
    'Procure uma farmácia com a placa "Aqui tem Farmácia Popular".',
};

// Codifica em base64 para mandar ao Postgres sem problema com vírgulas e aspas
const b64 = (obj) => Buffer.from(JSON.stringify(obj ?? {}), 'utf8').toString('base64');

// Monta a saída padrão de cada ramo (vai para "Juntar resposta" -> "Salvar conversa")
function fim(d, o) {
  return {
    usuario_hash: d.usuario_hash,
    acao: o.acao || 'salvar',
    novo_estado: o.novo_estado || d.estado_atual || 'novo',
    novo_contexto_b64: b64(o.novo_contexto !== undefined ? o.novo_contexto : (d.contexto || {})),
    evento: o.evento || '-',
    detalhe_b64: b64({ ...(o.detalhe || {}), canal: d.canal }),
    resposta: o.resposta,
  };
}

// Lê a resposta da API do Claude com segurança
function lerRespostaClaude(r) {
  if (!r || r.error || r.type === 'error') return { ok: false, erro: 'api' };
  if (r.stop_reason === 'refusal') return { ok: false, erro: 'recusa' };
  if (r.stop_reason === 'max_tokens') return { ok: false, erro: 'max_tokens' };
  const texto = (r.content || []).filter(b => b.type === 'text').map(b => b.text).join('').trim();
  if (!texto) return { ok: false, erro: 'vazio' };
  return { ok: true, texto };
}

// Monta o corpo da chamada ao Claude
function corpoClaude(system, content, max_tokens, schema) {
  const corpo = {
    model: MODELO_CLAUDE,
    max_tokens,
    system,
    messages: [{ role: 'user', content }],
    output_config: { effort: 'low' },
  };
  if (schema) corpo.output_config.format = { type: 'json_schema', schema };
  if (USAR_FALLBACK) corpo.fallbacks = 'default';
  return corpo;
}

// Texto em MAIÚSCULAS, sem acento e sem pontuação (para comparar comandos)
const normCmd = (s) => (s || '').normalize('NFD').replace(/[̀-ͯ]/g, '')
  .toUpperCase().replace(/[^A-Z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();

const cap = (s) => (s ? s.charAt(0).toUpperCase() + s.slice(1) : s);

// Resposta de reserva (sem IA) caso a redação do Claude falhe
function modeloResultado(fatos) {
  const linhas = fatos.itens.map((i) => {
    const nome = i.remedio_na_lista ? cap(i.remedio_na_lista) : `O remédio nº ${i.numero}`;
    const conc = i.concentracao_da_receita ? ' ' + i.concentracao_da_receita : '';
    switch (i.situacao) {
      case 'na_lista':
        return `✅ ${nome}${conc}: tá na lista e é de graça no Farmácia Popular.`;
      case 'na_lista_sem_concentracao':
        return `✅ ${nome}: tá na lista e é de graça (${(i.concentracoes_na_lista || []).join(', ')}). Confira se a da receita é essa.`;
      case 'concentracao_fora_da_lista':
        return `❌ ${nome}${conc}: nessa concentração não tá na lista. Procure a UBS (posto de saúde) ou a farmácia municipal.`;
      default:
        return `❌ ${nome}: não tá na lista. Procure a UBS (posto de saúde) ou a farmácia municipal.`;
    }
  });
  linhas.push(fatos.proximo_passo === 'pedir_cep' ? MSG.PEDIR_CEP : 'Se precisar de outra receita, é só mandar a foto.');
  return linhas.join('\n');
}
// ===== fim dos trechos comuns =====

// DECIDIR ROTA: olha o estado da conversa e a mensagem, e escolhe o caminho.
//   rota = 'fixa'      -> resposta pronta (sem IA)
//   rota = 'extrair'   -> ler receita/texto com o Claude
//   rota = 'resultado' -> pessoa confirmou: dizer se está na lista
//   rota = 'cep'       -> procurar farmácias pelo CEP
const ent = $('Entrada → formato padrão').first().json;
const conv = $input.first().json.r;

const d = {
  canal: ent.canal,
  usuario_hash: conv.usuario_hash,
  estado_atual: conv.estado,
  contexto: conv.contexto || {},
  texto: ent.texto || '',
  imagem_base64: ent.imagem_base64,
  imagem_mime: ent.imagem_mime,
  imagem_bytes: ent.imagem_bytes || 0,
  aviso: conv.expirou ? MSG.EXPIROU + '\n\n' : '',
};

const t = normCmd(d.texto);
const temImagem = !!d.imagem_base64;
const fixa = (o) => [{ json: { ...fim(d, o), rota: 'fixa' } }];
const seguir = (rota, extra = {}) => [{ json: { ...d, rota, ...extra } }];

const MAX_IMG = 3.7 * 1024 * 1024; // limite do Claude é 5 MB em base64
const MIMES_OK = ['image/jpeg', 'image/png', 'image/webp', 'image/gif'];
const ehSim = ['SIM', 'S', 'ISSO', 'ISSO MESMO', 'CERTO', 'TA CERTO', 'ESTA CERTO', 'CORRETO', 'OK', 'CONFIRMO'].includes(t) || t.startsWith('SIM ');
const ehNao = ['NAO', 'N', 'ERRADO', 'TA ERRADO', 'ESTA ERRADO'].includes(t) || t.startsWith('NAO ');
const ehSaudacao = ['OI', 'OIE', 'OLA', 'BOM DIA', 'BOA TARDE', 'BOA NOITE', 'AJUDA', 'INICIO', 'OI ZE', 'OLA ZE', 'ZE'].includes(t);

// Perguntas clínicas e dados sensíveis: resposta fixa, sem IA, em qualquer estado
const RE_CLINICA = /(QUAL A DOSE|QUAL DOSE|QUE DOSE|DOSE CERTA|DOSAGEM|AUMENTAR A DOSE|DIMINUIR A DOSE|QUANTOS? (COMPRIMIDOS?|GOTAS|VEZES)|POSSO TOMAR|PODE TOMAR|DA PRA TOMAR|EFEITO|COLATERA|INTERACAO|INTERAGE|MISTURAR|TROCAR|SUBSTITU|ALCOOL|CERVEJA|BEBIDA|GRAVIDA|AMAMENTA|PARAR DE TOMAR|ESQUECI DE TOMAR|SERVE PRA|SERVE PARA|PRA QUE SERVE|PARA QUE SERVE|CONTRAINDICA|ALERGIA|FAZ MAL|REACAO)/;
const RE_SENSIVEL = /\b(SENHA|CARTAO(?! (DO )?SUS)|PIX|CONTA BANCARIA|CONTA DO BANCO|AGENCIA|CVV|TOKEN|BOLETO|DADOS BANCARIOS)\b/;
const RE_CPF = /\b\d{3}\.?\d{3}\.?\d{3}-?\d{2}\b/;

function checarArquivo() {
  if (ent.tem_audio && !temImagem) return fixa({ resposta: MSG.AUDIO, evento: 'audio' });
  if (ent.outro_arquivo && !temImagem) return fixa({ resposta: MSG.IMAGEM_TIPO, evento: 'arquivo_invalido' });
  if (!temImagem) return null;
  if (!MIMES_OK.includes(d.imagem_mime)) return fixa({ resposta: MSG.IMAGEM_TIPO, evento: 'arquivo_invalido' });
  if (d.imagem_bytes > MAX_IMG) return fixa({ resposta: MSG.IMAGEM_GRANDE, evento: 'imagem_grande' });
  return null;
}

// 1) APAGAR vale em qualquer estado
if (t === 'APAGAR' || t === 'APAGAR MEUS DADOS') {
  return fixa({ resposta: MSG.APAGADO, acao: 'apagar', novo_estado: 'novo', novo_contexto: {}, evento: 'apagou' });
}

// 2) Consentimento: usuário novo só segue depois de responder SIM
if (d.estado_atual === 'novo') {
  const pedido = d.contexto.consentimento_pedido === true;
  if (pedido && (t === 'SIM' || t === 'S' || t.startsWith('SIM '))) {
    return fixa({ resposta: MSG.BOAS_VINDAS, acao: 'consentir', novo_estado: 'aguardando_receita', novo_contexto: {}, evento: 'consentiu' });
  }
  if (pedido && (t === 'NAO' || t === 'N' || t.startsWith('NAO '))) {
    return fixa({ resposta: MSG.CONSENTIMENTO_NAO, acao: 'apagar', novo_estado: 'novo', novo_contexto: {}, evento: 'recusou_consentimento' });
  }
  return fixa({ resposta: MSG.CONSENTIMENTO, novo_estado: 'novo', novo_contexto: { consentimento_pedido: true }, evento: pedido ? '-' : 'novo_usuario' });
}

// 3) Proteções (não mudam o estado)
if (RE_SENSIVEL.test(t)) return fixa({ resposta: MSG.NUNCA_PEDIMOS, evento: 'alerta_dado_sensivel' });
if (RE_CPF.test(d.texto)) return fixa({ resposta: MSG.NAO_PRECISA_CPF, evento: 'alerta_cpf' });
if (RE_CLINICA.test(t)) return fixa({ resposta: MSG.FORA_CLINICO, evento: 'fora_clinico' });
if (['RECOMECAR', 'CANCELAR', 'MENU', 'SAIR'].includes(t)) {
  return fixa({ resposta: MSG.RECOMECAR, novo_estado: 'aguardando_receita', novo_contexto: {}, evento: 'recomecou' });
}
{ const x = checarArquivo(); if (x) return x; }

// 4) Cada estado
switch (d.estado_atual) {
  case 'aguardando_confirmacao': {
    if (ehSim) {
      if (!(d.contexto.itens || []).length) {
        return fixa({ resposta: MSG.PEDIR_RECEITA, novo_estado: 'aguardando_receita', novo_contexto: {} });
      }
      return seguir('resultado');
    }
    if (ehNao) {
      return fixa({ resposta: MSG.CONFIRMACAO_NAO, novo_estado: 'aguardando_receita', novo_contexto: {}, evento: 'confirmacao_nao' });
    }
    if (temImagem || (t && !ehSaudacao)) return seguir('extrair'); // correção: lê de novo
    return fixa({ resposta: MSG.CONFIRMAR_DE_NOVO });
  }

  case 'aguardando_cep': {
    const digitos = (d.texto.match(/\d/g) || []).join('');
    if (!temImagem && digitos.length === 8) return seguir('cep', { cep: digitos });
    if (temImagem) return seguir('extrair'); // mandou outra receita
    if (ehNao) return fixa({ resposta: MSG.SEM_CEP, novo_estado: 'concluido', novo_contexto: {}, evento: 'sem_cep' });
    return fixa({ resposta: MSG.CEP_INVALIDO });
  }

  default: { // aguardando_receita ou concluido
    if (temImagem) return seguir('extrair');
    if (!t || ehSaudacao || ehSim || ehNao) {
      return fixa({ resposta: d.aviso + MSG.PEDIR_RECEITA, novo_estado: 'aguardando_receita', novo_contexto: {} });
    }
    return seguir('extrair');
  }
}

